PRAGMA foreign_keys=ON;
CREATE TABLE settings(id INTEGER PRIMARY KEY CHECK(id=1), name TEXT NOT NULL DEFAULT 'Mehran Grill', address TEXT DEFAULT '', phone TEXT DEFAULT '+923342233369', hours TEXT DEFAULT '4 PM – 4 AM', review_url TEXT DEFAULT '', origin TEXT DEFAULT '', tax_bps INTEGER NOT NULL DEFAULT 0 CHECK(tax_bps BETWEEN 0 AND 10000), tax_confirmed INTEGER NOT NULL DEFAULT 0, stamp_target INTEGER NOT NULL DEFAULT 5 CHECK(stamp_target BETWEEN 1 AND 50), stamp_mode TEXT NOT NULL DEFAULT 'per_coffee' CHECK(stamp_mode IN ('per_coffee','per_order')), comeback_days INTEGER NOT NULL DEFAULT 21 CHECK(comeback_days>=21), birthday_days INTEGER NOT NULL DEFAULT 0, offer_valid_days INTEGER NOT NULL DEFAULT 7, birthday_enabled INTEGER NOT NULL DEFAULT 0, comeback_enabled INTEGER NOT NULL DEFAULT 0, review_enabled INTEGER NOT NULL DEFAULT 0);
INSERT INTO settings(id) VALUES(1);
CREATE TABLE dining_tables(id TEXT PRIMARY KEY, label TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE categories(id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, position INTEGER NOT NULL DEFAULT 0);
CREATE TABLE menu_items(id TEXT PRIMARY KEY, category_id TEXT NOT NULL REFERENCES categories(id), name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', image TEXT DEFAULT '', available INTEGER NOT NULL DEFAULT 1, earns_stamp INTEGER NOT NULL DEFAULT 0, source_page INTEGER, source_note TEXT NOT NULL DEFAULT '', preorder INTEGER NOT NULL DEFAULT 0);
CREATE TABLE variants(id TEXT PRIMARY KEY, item_id TEXT NOT NULL REFERENCES menu_items(id) ON DELETE CASCADE, name TEXT NOT NULL DEFAULT 'Regular', price INTEGER NOT NULL CHECK(price>=0 AND price<=100000000));
CREATE TABLE addon_links(item_id TEXT NOT NULL REFERENCES menu_items(id), addon_item_id TEXT NOT NULL REFERENCES menu_items(id), PRIMARY KEY(item_id,addon_item_id));
CREATE TABLE customers(id TEXT PRIMARY KEY, name TEXT NOT NULL, phone TEXT NOT NULL UNIQUE, marketing_consent INTEGER NOT NULL DEFAULT 0, consent_at TEXT, birth_month INTEGER CHECK(birth_month BETWEEN 1 AND 12), birth_day INTEGER CHECK(birth_day BETWEEN 1 AND 31), visits INTEGER NOT NULL DEFAULT 0, spent INTEGER NOT NULL DEFAULT 0, last_visit TEXT, created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE customer_devices(token_hash TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES customers(id) ON DELETE CASCADE, expires_at TEXT NOT NULL);
CREATE TABLE recovery_codes(code_hash TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES customers(id) ON DELETE CASCADE, expires_at TEXT NOT NULL, used_at TEXT);
CREATE TABLE staff(id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','staff')), active INTEGER DEFAULT 1);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY, staff_id TEXT NOT NULL REFERENCES staff(id), expires_at TEXT NOT NULL);
CREATE TABLE orders(id TEXT PRIMARY KEY, reference TEXT NOT NULL UNIQUE, customer_id TEXT NOT NULL REFERENCES customers(id) ON DELETE CASCADE, table_id TEXT NOT NULL REFERENCES dining_tables(id), status TEXT NOT NULL DEFAULT 'new' CHECK(status IN ('new','preparing','ready','completed','cancelled')), payment_status TEXT NOT NULL DEFAULT 'unpaid' CHECK(payment_status IN ('unpaid','paid')), payment_method TEXT NOT NULL DEFAULT 'cash' CHECK(payment_method IN ('cash','card_terminal')), subtotal INTEGER NOT NULL CHECK(subtotal>=0), tax INTEGER NOT NULL CHECK(tax>=0), discount INTEGER NOT NULL DEFAULT 0 CHECK(discount>=0), total INTEGER NOT NULL CHECK(total=subtotal+tax-discount AND total>=0), tax_bps INTEGER NOT NULL DEFAULT 0, notes TEXT NOT NULL DEFAULT '', idempotency TEXT UNIQUE NOT NULL, request_hash TEXT NOT NULL, view_hash TEXT NOT NULL, qualified INTEGER NOT NULL DEFAULT 0, reward_id TEXT, created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')), qualified_at TEXT);
CREATE TABLE order_items(id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE, variant_id TEXT NOT NULL REFERENCES variants(id), item_id TEXT NOT NULL REFERENCES menu_items(id), name TEXT NOT NULL, variant_name TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 50), price INTEGER NOT NULL CHECK(price>=0), earns_stamp INTEGER NOT NULL DEFAULT 0, parent_line TEXT);
CREATE TABLE payments(id TEXT PRIMARY KEY, order_id TEXT NOT NULL UNIQUE REFERENCES orders(id) ON DELETE CASCADE, amount INTEGER NOT NULL, method TEXT NOT NULL, staff_id TEXT NOT NULL REFERENCES staff(id), created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE stamps(order_id TEXT PRIMARY KEY REFERENCES orders(id) ON DELETE CASCADE, customer_id TEXT NOT NULL REFERENCES customers(id) ON DELETE CASCADE, quantity INTEGER NOT NULL CHECK(quantity>0), created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE rewards(id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES customers(id) ON DELETE CASCADE, code TEXT UNIQUE NOT NULL, type TEXT NOT NULL CHECK(type IN ('loyalty','birthday','comeback')), cycle INTEGER, target INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'available' CHECK(status IN ('available','reserved','redeemed','expired')), expires_at TEXT, redeemed_at TEXT, order_id TEXT, created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE(customer_id,type,cycle));
CREATE TABLE offers(id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', discount_bps INTEGER NOT NULL DEFAULT 2000 CHECK(discount_bps BETWEEN 0 AND 10000), valid_days INTEGER DEFAULT 7, active INTEGER DEFAULT 1);
INSERT INTO offers VALUES('comeback','Welcome back','20% off your next order',2000,7,1);
INSERT INTO offers VALUES('birthday','Birthday treat','A complimentary eligible coffee',0,7,1);
CREATE TABLE campaigns(id TEXT PRIMARY KEY, type TEXT NOT NULL CHECK(type IN ('comeback','birthday','review')), message TEXT NOT NULL, offer_id TEXT REFERENCES offers(id), mode TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE recipients(id TEXT PRIMARY KEY, campaign_id TEXT NOT NULL REFERENCES campaigns(id), customer_id TEXT NOT NULL REFERENCES customers(id) ON DELETE CASCADE, dedupe_key TEXT UNIQUE NOT NULL, code TEXT UNIQUE, status TEXT NOT NULL DEFAULT 'prepared', provider_id TEXT UNIQUE, error TEXT, expires_at TEXT, sent_at TEXT, delivered_at TEXT, returned_order_id TEXT, redeemed_order_id TEXT, created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE(campaign_id,customer_id));
CREATE TABLE review_requests(customer_id TEXT PRIMARY KEY REFERENCES customers(id) ON DELETE CASCADE, due_at TEXT NOT NULL, prepared_at TEXT, recipient_id TEXT, clicked_at TEXT, confirmed_at TEXT, confirmation_method TEXT);
CREATE TABLE review_clicks(id TEXT PRIMARY KEY, customer_id TEXT REFERENCES customers(id) ON DELETE CASCADE, created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE audit_log(id INTEGER PRIMARY KEY AUTOINCREMENT, staff_id TEXT, action TEXT NOT NULL, entity TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE rate_limits(key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE INDEX order_time ON orders(created_at,status);
CREATE INDEX order_customer ON orders(customer_id,qualified,created_at);
CREATE INDEX customer_visit ON customers(last_visit,marketing_consent);
CREATE INDEX recipient_time ON recipients(customer_id,created_at,status);
CREATE INDEX recipient_status ON recipients(status,created_at);
CREATE TRIGGER validate_order_line BEFORE INSERT ON order_items BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM variants v JOIN menu_items m ON m.id=v.item_id WHERE v.id=NEW.variant_id AND m.id=NEW.item_id AND v.price=NEW.price AND m.available=1 AND m.preorder=0) THEN RAISE(ABORT,'menu_changed') END;
END;
CREATE TRIGGER qualify_order AFTER UPDATE OF status,payment_status ON orders WHEN NEW.status='completed' AND NEW.payment_status='paid' AND OLD.qualified=0 BEGIN
 UPDATE orders SET qualified=1,qualified_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=NEW.id;
 UPDATE customers SET visits=visits+1,spent=spent+NEW.total,last_visit=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=NEW.customer_id;
 INSERT OR IGNORE INTO stamps(order_id,customer_id,quantity) SELECT NEW.id,NEW.customer_id,CASE WHEN (SELECT stamp_mode FROM settings WHERE id=1)='per_order' THEN 1 ELSE SUM(quantity) END FROM order_items WHERE order_id=NEW.id AND earns_stamp=1 AND NEW.reward_id IS NULL HAVING SUM(quantity)>0;
 INSERT OR IGNORE INTO review_requests(customer_id,due_at) SELECT id,strftime('%Y-%m-%dT%H:%M:%fZ','now','+2 hours') FROM customers WHERE id=NEW.customer_id AND visits=2;
 UPDATE recipients SET returned_order_id=COALESCE(returned_order_id,NEW.id) WHERE customer_id=NEW.customer_id AND status IN ('sent','delivered','read') AND sent_at<=NEW.created_at AND expires_at>=NEW.created_at;
END;
CREATE TRIGGER award_reward AFTER INSERT ON stamps BEGIN
 INSERT OR IGNORE INTO rewards(id,customer_id,code,type,cycle,target)
 WITH RECURSIVE cycles(n) AS (SELECT 1 UNION ALL SELECT n+1 FROM cycles WHERE n < (SELECT COALESCE(SUM(quantity),0)/(SELECT stamp_target FROM settings WHERE id=1) FROM stamps WHERE customer_id=NEW.customer_id))
 SELECT lower(hex(randomblob(16))),NEW.customer_id,'FREE-'||upper(hex(randomblob(5))),'loyalty',n,(SELECT stamp_target FROM settings WHERE id=1) FROM cycles WHERE n <= (SELECT COALESCE(SUM(quantity),0)/(SELECT stamp_target FROM settings WHERE id=1) FROM stamps WHERE customer_id=NEW.customer_id);
END;
CREATE TRIGGER prevent_reopen BEFORE UPDATE OF status,payment_status ON orders WHEN OLD.qualified=1 AND (NEW.status!='completed' OR NEW.payment_status!='paid') BEGIN SELECT RAISE(ABORT,'qualified_order_locked'); END;
